/**
 * A PAGE WITHDRAWN ON PURPOSE SHOULD SAY SO, NOT JUST STOP EXISTING.
 *
 * WHAT HAPPENED. The AI agents post was published on 10 September and retired
 * on 13 October, because nothing a customer reads may describe this work as
 * generated by AI. The decision was right and it stands. What nobody did was
 * tell the search engines, and the post had been live and indexable for over a
 * month, so Google had it. Six weeks later Search Console reported pages "not
 * indexed — Not found (404)".
 *
 * WHY 410 AND NOT 404. They are not the same answer. A 404 means "no page at
 * this address", which a crawler reasonably reads as "perhaps not yet, or
 * perhaps a mistake" — so it keeps the URL on file and keeps coming back, and
 * keeps reporting it. A 410 means "there was a page here and it is
 * permanently gone", and a crawler drops it. The difference is weeks of a
 * withdrawn URL sitting in a report somebody has to keep explaining.
 *
 * WHY NOT REDIRECT IT TO THE BLOG INDEX. Because it would be a lie with a
 * side effect. A specific article redirected to a listing page is what Google
 * calls a soft 404; it gets treated as one anyway, and meanwhile anyone who
 * followed an old link lands somewhere that does not answer them. There is no
 * replacement for this post and there is never going to be one. Saying that
 * plainly is the honest answer and the one that clears fastest.
 *
 * IT READS THE SCHEDULE, NOT A LIST WRITTEN OUT BY HAND. RETIRED comes from
 * content/blog/schedule.json, so retiring another post in the usual way gets
 * this behaviour with no code change — and un-retiring one removes it, which
 * is the only way the page ever comes back, and a decision somebody has to
 * make on purpose.
 */
import { RETIRED } from "./blog.js";

/** Slugs that were published and have been deliberately withdrawn. */
export const retiredSlugs = () => new Set(RETIRED.map((p) => p.slug));

/**
 * Every address a retired post could be asked for. The canonical form is
 * extensionless, but Google indexed whatever was live at the time and old
 * links elsewhere carry the .html, so both have to answer.
 */
export function retiredPaths() {
  const out = new Set();
  for (const slug of retiredSlugs()) {
    out.add(`/blog/${slug}`);
    out.add(`/blog/${slug}/`);
    out.add(`/blog/${slug}.html`);
  }
  return out;
}

/**
 * THE PAGE NAMES NOTHING, AND THAT IS THE POINT.
 *
 * The first version printed the withdrawn post's title — "It was published as
 * 'AI agents in construction'" — which put the subject back on a page a
 * customer reads, which is the precise thing the withdrawal was for. A test
 * caught it. Echoing the title of a post you removed for its content undoes
 * the removal in the one place everyone who followed an old link will land.
 *
 * So this page is deliberately generic, and it stays generic for every future
 * retirement, whatever the reason for it.
 */
function page() {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="robots" content="noindex">
<title>Withdrawn — ETABLIX</title>
<style>
  :root { color-scheme: light dark; }
  body { margin:0; font:16px/1.6 system-ui,-apple-system,"Segoe UI",sans-serif;
         background:#faf8f5; color:#20242a; display:grid; place-items:center; min-height:100vh; padding:24px; }
  main { max-width:34rem; }
  h1 { font-size:1.4rem; margin:0 0 1rem; }
  p { margin:0 0 1rem; }
  a { color:#8a6a2f; }
  @media (prefers-color-scheme: dark) { body { background:#16181c; color:#e8e6e3; } a { color:#c9a765; } }
</style>
</head>
<body>
<main>
  <h1>This article has been withdrawn</h1>
  <p>It was taken down deliberately rather than moved or renamed, so there is no newer version of it to send you to.</p>
  <p><a href="/blog">Read what is on the blog now</a> &middot; <a href="/">ETABLIX home</a></p>
</main>
</body>
</html>
`;
}

/**
 * Mounted ahead of the static handler, so a retired address answers 410 rather
 * than falling through to whatever the file server says about a missing file.
 */
export function retiredUrls() {
  return function retiredUrlHandler(req, res, next) {
    // Only GET and HEAD. Anything else is not a crawler and not a reader.
    if (req.method !== "GET" && req.method !== "HEAD") return next();
    const pathname = String(req.path || "");
    const m = /^\/blog\/([^/]+?)(?:\.html)?\/?$/.exec(pathname);
    if (!m) return next();
    const slug = m[1];
    if (!retiredSlugs().has(slug)) return next();

    res.status(410);
    res.set("Cache-Control", "public, max-age=86400");
    res.set("X-Robots-Tag", "noindex");
    if (req.method === "HEAD") return res.end();
    return res.type("html").send(page());
  };
}
